import java.util.concurrent.*;

public class ObservingThreadPoolExecutor extends ThreadPoolExecutor {
    private final String poolName;

    public ObservingThreadPoolExecutor(String poolName, int core, int max, BlockingQueue<Runnable> q) {
        super(core, max, 60L, TimeUnit.SECONDS, q, r -> {
            Thread t = new Thread(r, poolName + "-worker");
            t.setUncaughtExceptionHandler((th, ex) -> report(poolName, ex));
            return t;
        });
        this.poolName = poolName;
    }

    @Override
    protected void afterExecute(Runnable r, Throwable t) {
        super.afterExecute(r, t);
        if (t == null && r instanceof Future<?> future && future.isDone() && !future.isCancelled()) {
            try {
                future.get();
            } catch (CancellationException ignored) {
                // Normal cancellation
            } catch (ExecutionException ee) {
                t = ee.getCause();
            } catch (InterruptedException ie) {
                Thread.currentThread().interrupt();
            }
        }
        if (t != null) {
            report(poolName, t);
        }
    }

    public static Runnable safePeriodic(String jobName, Runnable task) {
        return () -> {
            try {
                task.run();
            } catch (Exception ex) {
                report(jobName, ex); // Keep scheduler alive for next tick
            }
        };
    }

    private static void report(String source, Throwable t) {
        // Log with traceId + increment async_task_exceptions_total{pool=source}
        System.err.println("[ASYNC_ERROR] source=" + source + " msg=" + t);
        t.printStackTrace(System.err);
    }
}

// Helper for CompletableFuture that guarantees observation without forcing boilerplate
public static <T> CompletableFuture<T> observe(String op, CompletableFuture<T> cf) {
    return cf.whenComplete((res, ex) -> {
        if (ex != null) report(op, ex);
    });
}

